      "levelId": "pre-nursery",
      "levelName": "Pre-Nursery",
      "ageBand": "2-3",
      "category": "phonics",
      "title": "Alphabet and sound awareness",
      "text": "Explore letter names and sounds through songs, stories, actions and the child's name. Formal systematic phonics is not required in Pre-Nursery. Use interesting animal sounds and rhythmic clapping to explore words, syllables and rhyme.",
