      "levelId": "pre-nursery",
      "levelName": "Pre-Nursery",
      "ageBand": "2-3",
      "category": "reading",
      "title": "Enjoy a story together",
      "text": "Share one English story daily with a story basket, toys or puppets. Let children handle a book and turn pages; talk about pictures, predict what happens next, and act out the story.",
