      "ageBand": "2-3",
      "category": "writing",
      "title": "Mark-making and sensory letters",
      "text": "Offer crayons, thick chalk and markers for drawing and pattern-making. Trace letters with fingers and explore letter shapes using play-dough, blocks, puzzles and loose parts.",
