      "category": "phonics",
      "title": "Alphabet names and sounds",
      "text": "Explore letter names and sounds alphabetically, generally one letter every two days, adapting to each child's development. Use rhymes, rhythm, art and a hand-held mirror. Build phonological and phonemic awareness; the guide describes this as preparation rather than systematic phonics teaching.",
