      "text": "nouns/verbs/adjectives     listed below,  although   at this\n                                                                   stage,  they cannot   use these  words   together.  In\n                                                                   pre-nursery,   children predominantly     learn and\n                                                                   understand    the usage   ofnouns.\n    School   life                                                 Everyday   Sentences                                                     Greeting  politely\n     hello,   school,    kindergarten,     classroom,     good     Interrogative   Sentence                                                 Able  to accurately   respond   to greeting  sentences,\n     morning,    goodbye,    bag,  backpack,    book,  marker,          What   isyour  name?    -XXX.                                      e.g. “hello/Good    Morning/How      are you?/How\n     brush,   chair,  table,   door,  scissors,   glue,  paper,         How   are you  today?                                              old  are you?  /What's   your  name?/   My   name   is\n     playground                                                         What’s   the weather   like today?                                 [Name].Nice    to meet   you.\"\n    Things   to wear                                                   What   isthis? / Is this…?                                         Asking  politely\n     hat,  shoes, socks,  pants,  coat                                  Can  you  …?                                                        With  the  guidance   of teachers,  able  to ask  for help\n    My   family                                                        Do  you  like…?/What…do      you  like?                             by saying  ‘Help(me)’.\n     father,  mother,   grandma,    grandpa,   brother,  sister,        Who   isshe/he?                                                     With  the  guidance   of teachers,   able to  use ‘please’\n     baby,  pets  (dog, cat, bird, rabbit), home                        How   many…?                                                        in a range  of situations,  e.g.during   snack  time, able\n    Me   and  my  body                                                 Where   is …?  – Here.  (Use ‘here’  to answer                      to use  ‘apple,  please’  or ‘more,   please’  to express\n     head,  face,  hand,  foot, eyes, ears,  mouth,   nose               ‘where’  questions   or pointing  to the  right                     themselves.\n     Describing  people                                                 directions  instead  of saying  a word)                            Helping  friends\n     happy,   sad, angry                                                What   isyour  favorite…?                                           Understand    “Please   help  me   find (the  toys)  / Can\n    Time                                                               What   can  you see/hear?                                           you help  me…please?”     and  show   willingness  to help\n     today,  morning,   afternoon                                       What   would   you  liketoeat/drink?                                others.\n    Weather                                                       School  daily  lifeinstructional  English  (able  to                      Able  to say  ‘thank  you’  in time   when   getting  help\n     sunny,   rainy, hot, cold, snow,  rainbow,   sun              understand    and  follow all of the listed instructions                  from  others.\n    Colors  and  shapes                                           below)                                                                   Sharing\n     red,   yellow,  green,    blue,  orange,    pink,  purple,    E.g.                                                                      Understand     ‘Can  you   share   …with    XXX?   /  Let’s\n     black,  white,   brown,   triangle,  square,  circle, star,        Wash   your  hands.                                                 share…   / let’splay  together’   and  willingly take  and\n     heart,  round                                                      Brush  your  teeth.                                                 share  turns with  teacher’s  support   and  guidance.\n    Numbers     one  to ten                                            Let’s go  to…\n    Food"
