      "text": "apple, banana,   pear,  strawberry,    orange,                      It’sclean  up/circle/lunch/snack/play       time.                  Thinking   of others\n      watermelon,     pizza, cake,  cookies,  bread,  rice,               Circle time.  Go  to the carpet.                                   When   making   mistakes,   show   willingness  to say\n      noodles,  chicken,  fish, pumpkin,    carrot, potato,               Please  siton  the  mat.                                           ‘Sorry’ to others  and  able  to show   empathy    towards\n      egg, water,  ice cream,   milk, yummy,    lollipop                  Please  sitdown/stand      up.                                     the feelings  of others.\n     Animals                                                             Come   here/in.\n      elephant,  monkey,    tiger, lion, bear, snake,  zebra,             Line up  please.                                              Please   be cautious   during   situations  when   a child  shows\n      sheep,  horse,  fish,frog,  dog, cat, duck,  bird,                  Attention   please.                                           anxiety   in a conflict situation,  for example,    refuses  to\n      butterfly, caterpillar, panda,   shark,  crocodile,                 Put the  toys  away.                                          say  sorry.  We  need   to be  aware   of the  effects that  the\n      dolphin,  bee,  pig,rabbit,  cow,  spider,  turtle,                 Put the  blocks  in the  box.                                 children’s   social and  emotional    development      have  on\n      dinosaur,  zoo,  sea, farm,  tree, flower                           Turn left/right/around.                                       their  behaviour.    To  be  sure  that  we  are  implementing\n     Transports                                                          One  by  one  please.                                         the  correct   strategies  in our  practice,  it is best  to keep\n      plane, car, train, ship, bus,  truck, bike,  boat,                  No  pushing/touching/talking.                                 up  to date  with  research.\n      wheels,  fast, slow,  up, down                                      It’syour  turn.\n     Story time                                                          Wait  for your  turn  please.\n      princess,  prince, monster,   pirate,  doctor,  nurse,              Hurry  up/slow   down.\n      cold, fever, sick, medicine,   bandage                              Be careful/watch     out!\n                                                                          Clap your  hands.\n                                                                    Grammar     Knowledge\n                                                                          Nouns\n                                                                          KEY  VOCABULARY\n                                                                          Verbs\n                                                                           open,  close,  like, love,  walk,  run,  jump,   hop,   go,\n                                                                           drink,  eat,  sleep,  read,   sing, dance,    play, climb,\n                                                                           push,   pull, sit,  stand,   taste,  smell,   listen, talk,\n                                                                           touch,  draw,  color\n                                                                          Adjectives\n                                                                           happy,  sad,  angry,   great,  yummy,    big, small,  fast,\n                                                                           slow, sunny,   rainy, hot, cold, red,  yellow,"
