      "text": "Ways   to Share   Books    with  Babies   &  Toddlers\n          Make    Sharing  Books  Part  Of Every  Day                                             Make   the  Story  Come   Alive\n           Read   or share  stories at circletime  or library time.                                 Create  voices  for the story  characters  and  use your  body  to tell the\n          Have   Fun                                                                               story.\n           Children  can  learn from   you that  books  are fun, which   isan important            Make   It Personal\n           ingredient   inlearning  to read.                                                        Talk  about  your  own  family, pets, or community     when   you are\n          Talk or  Sing About   the Pictures                                                       reading  about   others  ina story.\n           You  do  not have  to read  the words   to tella story.                                 Ask  Questions   About   the Story,  and  Let Children  Ask  Questions\n          Let  Children  Turn  the Pages                                                           Too!\n           Babies  need   board  books  and  help  turning pages,  but  a three-year-old            Use  the  story to engage   inconversation    and to talk about  familiar\n           can  do  italone. Remember,     it'sOK  to skip pages!                                   activities and  objects.\n           Show   Children  the CoverPage                                                         Let  Children  Tellthe  Story\n           Explain  what  the  story isabout.                                                       Children  as young   as three  years old  can memorize    a story, and  many\n                                                                                                    children  love to be  creative  through  storytelling.\nPN  songs   &  Fingerplay\nEnglish  songs  played  in pre-nursery    class are  mainly  nursery   rhymes.   Young   children  should   be able  to follow  the  rhythm,   make   corresponding     actions,  and  enjoy\nparticipating  in  the  acting. They   are  not  required   to sing  the  whole   English  rhymes    or  finger-play  songs   on  their  own   as long  as  they  can  sing  together   with\nteachers  or  with the  music."
