      "text": "13 Tips  for Reading   to  a Group\n1.  Be  sure  allchildren   can  see  and  hear  the  story.\n2.  Choose    a story  that will appeal   to your   audience    and  suit the  children'  s attention   span.\n3.  Choose    a book   with  bright  and  large  illustrations\n4.  Provide   an  alternate  activity  for those   who   lose interest.\n5.  Choose    books   that invite  participation   though    repeated   verses   or rhymes.\n6.  Start  by grabbing    their attention   with  \"magic   story  dust\"  or  a calming   finger-play.\n7.  Ask  questions    to set the  stage  for listening.  For  example,\"What      do  you  think  will happen    to Miffy  mouse?\"\n8.  Substitute   the  children's  names    for character    names   to  add  interest.\n9.  Be  flexible. Skip  or alter parts  of  a book   as the  needs   of your  young   listeners'  dictate.\n10. Use  props/puppets      to bring  a story  to  life.\n11. Try a  new  introduction    or  attention   grabber   before   starting a  story.\n12. Pick  a book   the children   are  familiar with.  Add   their names    or  make   sillymistakes   to  get their  attention\n13. Try asking   the  children  to predict   what   willhappen    next.\nIn addition,   although   it isoften   tempting    for teachers    to find  books   that  are  precisely  relevant   to  their current   theme    or  topic, it isnot  always    a\nstrict rule of thumb.    Children   make    connections     between     phenomena      and   concepts    by themselves,     and  it isgood   to  add  variety.  When     choosing\na book,  focus   on  the  book   itselfprimarily   rather   than  worrying    about   whether     or not  itincludes   specific  vocabulary     you  are  teaching.\nNursery   Rhymes    以下选取了一些比较经典的小班英文儿歌，要求幼儿能独立唱出来。\nASailorWent  ToSea                                            Asailorwentto knee,knee,knee                                  Asailorwentto chop,chop,chop\n                                                              Tosee whathe couldknee, knee,knee                             Tosee whathe couldchop, chop,chop\nAsailorwentto sea,sea,sea                                     Butallthathecouldknee,knee, knee                              Butallthathecouldchop, chop,chop\nTosee whathe couldsee,see,see                                 Was thebottom ofthe deep blueknee,knee,knee!                  Was thebottom ofthe deep bluechop,chop,chop!\nButallthathecouldsee,see,see                                  Sea,sea,sea                                                   Knee,knee,knee\nWas thebottom ofthe deep bluesea,sea,sea!"
