      "text": "Kindergarten             1（4-5yrs）\n                                               COMMUNICATION              &  LANGUAGE        (LISTENING/UNDERSTANDING/SPEAKING)\nIntroduction\nThe following   section  outlines the  end  of year  expectations   for K1  Class children  for vocabulary,  grammar     and  functional  language(listening   &  speaking).  It isimportant   to note\nthat this process  happens    organically  over time  and  can’t  be rushed.  Find  opportunities   during  interactive  play as  well as class time  to introduce   new   words  and  sentences   and\ntheir meaning   through   context  and  children's  interests. There  are effective  methods   to  achieve  the end  of year  goals, such  as:\n    The  use  of nursery  rhymes,   stories  and  readers  that  repeat  or emphasize   a particular  sentence   structure.\n    Routine:   Children  learn  language   though  repetition.  Use  the daily routines   and circle time  to drilllanguage.\n    Play:  Teachers   should  think  carefully about   how  they  teach  specific  words   and  sentences   whilst guiding   their play. Incorporate   play-based   activities that  are inviting and\n     interesting.\nBelow  you  will find a listof topics in each  category   that the  children  should  be  familiar with  by the  end  of the year. The  methods    above   not only  build language   proficiency   but\nalso nurture  a love for learning  and  curiosity.\nKEY  VOCABULARY                                                    GRAMMAR                                                            LISTENING     &  SPEAKING\nEnd  of Year Expectations:                                         End  of Year  Expectations:                                        End  of Year  Expectations:\nChildren  can   grasp   and   say  a  wider   range    of daily    With  the increase  in the  number   of vocabulary,   phrases      In addition  to the  ability inthe  guide  for 3-4 years  old, by\nvocabulary    about   a   variety  of  different   topics   and    and  sentence   patterns  learnt by them,   K1 children            the  end  of  the year,  children  should   be  able  to use  the\nthemes.                                                            should  be able  to answer   questions  and  express               following   functional   language    in  appropriate   contexts.\n                                                                   themselves   in complete   sentences.                              The   goal  isfor  each  child to  demonstrate    the  ability to\n                                                                                                                                      use   each   functional    phrase   correctly   in  at   least  3\n                                                                                                                                      different  situations.\n    School   life                                                 Everyday   Sentences                                                  Asking  for Help:\n     desk,   ruler, eraser,  cushion,   beanbag,    bookshelf,     Understand    and  able to answer   the  following  new                  Ask  for  help  in at  least 3  different  activities each\n     sharpener,    glitter,journal,  newsletter,  clock,  map,     sentences：                                                               week\n     magnifying    glass, palette, tape,  globe, stapler, pins,         Where   are you  going?                                            \"Can  you  help  me?\"\n     highlighter,  library, drama,   science,  music,  creative         How   do you  go to…?                                              \"I need  help.\"\n     art,  mathematics,    literacy, toy,  doll, snack,  lunch,         What   are you  doing?                                             \"Please  help  me.\"\n     bathroom,       basket,     tissue,    tablet,    speaker,         Where   do  you  live?                                             \"Help,  please.\"\n     scooter,  bike, tricycle, wall                                     Where   is …?                                                      \"I can't do this.\"\n    Things   to wear                                                   What   do you  want  to do?                                        \"Can  you  open   this?\"\n     shirt,  vest,  jeans,  skirt, tights,  jumper,   slippers,         Why…?                                                              \"Can  you  reach  that?\""
