      "text": "Kindergarten              2（5-6yrs）\n                                               COMMUNICATION             &   LANGUAGE        (LISTENING/UNDERSTANDING/SPEAKING)\nIntroduction\nThe following   section outlines  the  end  of year  expectations   for K2 Class  children for vocabulary,   grammar    and  functional  language(listening    & speaking).  It isimportant   to note\nthat this process   happens   organically  over  time  and  can’t  be rushed.   Find  opportunities   during  interactive  play  as well as  class time  to introduce   new   words,  sentences   and\nphrases  and  their meaning   through   context.  There  are effective  methods   to achieve   the end  of year  goals, such  as:\n    The  use  of nursery  rhymes,   stories  and  readers  that repeat  or emphasize    a particular  sentence   structure.\n    Routine:   Children  learn language   though   repetition.  Use  the daily routines  and  circle time to  drilllanguage.\n    Play:  Teachers  should   think carefully  about  how   they  teach  specific words   and  sentences   whilst  guiding  their play. Incorporate   play-based   activities that  are inviting and\n     interesting.\nBelow  you  will find a listof topics  in each  category  that  the children  should   be familiar  with and  able  to have  an  understanding    of by  the end  of the  year. The  methods    above\nnot only build  language   proficiency  but also  nurture  a love for learning  and  curiosity.\nVOCABULARY                                                         GRAMMAR                                                            LISTENING     &  SPEAKING\nEnd  of Year Expectations:                                         End  of Year Expectations:                                         End  of Year Expectations:\nChildren  can   grasp  and   attempt   to  say  the  following     K2  children   should   learn  how    to  raise  questions    in   In addition  to the ability in the guide  for 4-5 years  old, by\ndaily vocabularies,    understand    the  meaning,    and   use    English, and  answer   or express  themselves   in English  ina    the end   of the  year, children  should   be  able  to use  the\nthem  in real life.For  words  that  meet  the  spelling rules,    more  abundant    and  complete   way.                             following   functional  language    in  appropriate    contexts.\nthey can  try tospell and  write  the words   down.                                                                                   The  goal  is for each  child  to demonstrate     the ability to\n                                                                                                                                      use  each    functional   phrase    correctly  in  at   least  3\n                                                                                                                                      different situations.\n    School   life                                                 Everyday   Sentences                                                    Making   Predictions\n      instruments,    tambourine,      xylophone,     triangle,    Examples:                                                               Make    predictions    during   reading    or  storytelling\n      shake,  cymbals,   skipping  rope,  skating, basketball,         Whose…is     this?/Who    is/are…?                                 activitiesat least once  per  week.\n      football,   balloon,   goal,   jungle    gym,    frisbee,        What   time  is it?                                                \"Ithink  itwillrain.\"\n      magnet,    balance    scale,  microscope,     telescope,         What   can  you  find…?/What…can       we  …?                      \"The  sun will shine.\"\n      calculator, clips,drawing   pins, hole  puncher,   stairs,       Which   be/do...?   Which   one…is/do…?                            \"Itwill be hot  tomorrow.\"\n      hand  rail,corridor, lobby,  dining  room,  playground,          Shall  we…?                                                        \"We  will go to the  park.\"\n      baseball, paddling   pool, swimming    pool                      Where    are you  going?/How     do  you  go to…?                  \"The  flowers  willbloom.\"\n    Things   to wear                                                  How   many    …are  there?                                         \"The  dog  willbark.\"\n     bracelet,   anklet,   ring,  earring,   mitten,   glasses,        How   do  we/you    use…?                                          \"The  cat willsleep.\"\n     sneakers,   trainers, crown,  pocket,  uniform                    What   are  you  doing?                                            \"The  bird willfly.\""
